import unittest
import mock
from mock import patch
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.pages.bts_basic_info import BtsBasicInfo
from selenium.common.exceptions import TimeoutException


class TestBtsBasicInfo(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.bts_basic_info = BtsBasicInfo()

    def test_check_activate_plan_status(self):
        self.bts_basic_info.get_text_by_xpath = mock.Mock()

        self.bts_basic_info.check_activate_plan_status()
        self.bts_basic_info.get_text_by_xpath.assert_called_once()

    def test_get_bts_id(self):
        self.bts_basic_info.get_text_by_xpath = mock.Mock()

        self.bts_basic_info.get_bts_id()
        self.bts_basic_info.get_text_by_xpath.assert_called_once()

    def test_get_bts_status(self):
        self.bts_basic_info.get_text_by_xpath = mock.Mock()

        self.bts_basic_info.get_bts_status()
        self.bts_basic_info.get_text_by_xpath.assert_called_once()

    def test_get_bts_version(self):
        self.bts_basic_info.get_text_by_xpath = mock.Mock()

        self.bts_basic_info.get_bts_version()
        self.bts_basic_info.get_text_by_xpath.assert_called_once()

    def test_connect_to_bts_if_disconnected__with_dropdown_list(self):
        expected_timeout = 15
        self.bts_basic_info._check_status_bar_menu_button_type = mock.Mock(return_value=True)
        self.bts_basic_info._reconnect_with_dropdown_list = mock.Mock()

        self.bts_basic_info.connect_to_bts_if_disconnected(expected_timeout)

        self.bts_basic_info._check_status_bar_menu_button_type.assert_called_once()
        self.bts_basic_info._reconnect_with_dropdown_list.assert_called_once_with(expected_timeout)

    def test_connect_to_bts_if_disconnected__without_dropdown_list(self):
        expected_timeout = 20
        self.bts_basic_info._check_status_bar_menu_button_type = mock.Mock(return_value=False)
        self.bts_basic_info._reconnect_without_dropdown_list = mock.Mock()

        self.bts_basic_info.connect_to_bts_if_disconnected(expected_timeout)

        self.bts_basic_info._check_status_bar_menu_button_type.assert_called_once()
        self.bts_basic_info._reconnect_without_dropdown_list.assert_called_once_with(expected_timeout)

    def test_can_be_connected_to_bts_without_dropdown_inside_connected(self):
        dropdown_inside = False
        expected_timeout = 12
        xpath = self.bts_basic_info._CONNECT_DISCONNECT_BUTTON_XPATH
        self.bts_basic_info.get_attribute_by_xpath = mock.Mock(return_value='Connect')

        result = self.bts_basic_info._can_be_connected_to_bts(dropdown_inside, expected_timeout)

        self.bts_basic_info.get_attribute_by_xpath.assert_called_once_with(xpath, 'ui-tooltip',
                                                                           expected_timeout)
        self.assertEqual(result, True)

    def test_can_be_connected_to_bts_without_dropdown_inside_disconnected(self):
        dropdown_inside = False
        expected_timeout = 9
        xpath = self.bts_basic_info._CONNECT_DISCONNECT_BUTTON_XPATH
        self.bts_basic_info.get_attribute_by_xpath = mock.Mock(return_value='Disconnect')

        result = self.bts_basic_info._can_be_connected_to_bts(dropdown_inside, expected_timeout)

        self.bts_basic_info.get_attribute_by_xpath.assert_called_once_with(xpath, 'ui-tooltip',
                                                                           expected_timeout)
        self.assertEqual(result, False)

    def test_can_be_connected_to_bts_with_dropdown_inside_connected(self):
        dropdown_inside = True
        expected_timeout = 11
        xpath = self.bts_basic_info._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH
        web_element = mock.Mock()
        web_element.text = 'Connect'
        self.bts_basic_info.driver.find_element_by_xpath = mock.Mock(return_value=web_element)

        result = self.bts_basic_info._can_be_connected_to_bts(dropdown_inside, expected_timeout)

        self.bts_basic_info.driver.find_element_by_xpath.assert_called_once_with(xpath)
        self.assertEqual(result, True)

    def test_can_be_connected_to_bts_with_dropdown_inside_disconnected(self):
        dropdown_inside = True
        expected_timeout = 11
        xpath = self.bts_basic_info._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH
        web_element = mock.Mock()
        web_element.text = 'Disconnect'
        self.bts_basic_info.driver.find_element_by_xpath = mock.Mock(return_value=web_element)

        result = self.bts_basic_info._can_be_connected_to_bts(dropdown_inside, expected_timeout)

        self.bts_basic_info.driver.find_element_by_xpath.assert_called_once_with(xpath)
        self.assertEqual(result, False)

    def test_check_status_bar_menu_button_type_with_dropdown_list(self):
        xpath = self.bts_basic_info._STATUS_BAR_MENU_BUTTON_ELIPSIS
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock()

        result = self.bts_basic_info._check_status_bar_menu_button_type()

        self.bts_basic_info.wait_for_visibility_by_xpath.\
            assert_called_once_with(xpath=xpath, timeout=5)
        self.assertEqual(result, True)

    def test_check_status_bar_menu_button_type_without_dropdown_list(self):
        xpath = self.bts_basic_info._STATUS_BAR_MENU_BUTTON_ELIPSIS
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock(side_effect=TimeoutException)

        result = self.bts_basic_info._check_status_bar_menu_button_type()

        self.bts_basic_info.wait_for_visibility_by_xpath.\
            assert_called_once_with(xpath=xpath, timeout=5)
        self.assertEqual(False, result)

    def test_reconnect_with_dropdown_list_can_be_connected_to_bts(self):
        status_bar_xpath = self.bts_basic_info._STATUS_BAR_MENU_BUTTON
        dropdown_list_button_xpath = self.bts_basic_info._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH
        expected_timeout = 18
        dropdown_inside = True
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock()
        self.bts_basic_info.click_enabled_element = mock.Mock()
        self.bts_basic_info._can_be_connected_to_bts = mock.Mock(return_value=True)
        self.bts_basic_info.wait_for_text_not_present_in_element = mock.Mock()

        self.bts_basic_info._reconnect_with_dropdown_list(expected_timeout)

        self.bts_basic_info.wait_for_visibility_by_xpath.assert_called_once_with(status_bar_xpath,
                                                                                 timeout=10)
        self.bts_basic_info._can_be_connected_to_bts.assert_called_once_with(dropdown_inside=dropdown_inside)
        self.bts_basic_info.wait_for_text_not_present_in_element.\
            assert_called_once_with((By.XPATH, dropdown_list_button_xpath), 'Connect', timeout=expected_timeout)
        self.assertEqual([mock.call((By.XPATH, status_bar_xpath), timeout=10),
                          mock.call((By.XPATH, dropdown_list_button_xpath), timeout=expected_timeout)],
                         self.bts_basic_info.click_enabled_element.mock_calls)

    def test_reconnect_with_dropdown_list_cant_be_connected_to_bts(self):
        status_bar_xpath = self.bts_basic_info._STATUS_BAR_MENU_BUTTON
        expected_timeout = 18
        dropdown_inside = True
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock()
        self.bts_basic_info.click_enabled_element = mock.Mock()
        self.bts_basic_info._can_be_connected_to_bts = mock.Mock(return_value=False)
        self.bts_basic_info.wait_for_text_not_present_in_element = mock.Mock()

        self.bts_basic_info._reconnect_with_dropdown_list(expected_timeout)

        self.bts_basic_info.wait_for_visibility_by_xpath.assert_called_once_with(status_bar_xpath,
                                                                                 timeout=10)

        self.bts_basic_info._can_be_connected_to_bts.assert_called_with(dropdown_inside=dropdown_inside)
        self.assertEqual([mock.call((By.XPATH, status_bar_xpath), timeout=10)],
                         self.bts_basic_info.click_enabled_element.mock_calls)
        self.bts_basic_info.wait_for_text_not_present_in_element.assert_not_called()

    def test_reconnect_without_dropdown_list_can_be_connected_to_bts(self):
        expected_timeout = 5
        button_xpath = self.bts_basic_info._CONNECT_DISCONNECT_BUTTON_XPATH
        bts_id_xpath = self.bts_basic_info._BTS_ID_XPATH
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock()
        self.bts_basic_info._can_be_connected_to_bts = mock.Mock(return_value=True)
        self.bts_basic_info.wait_for_text_not_present_in_element = mock.Mock()
        self.bts_basic_info.click_enabled_element = mock.Mock()

        self.bts_basic_info._reconnect_without_dropdown_list(expected_timeout)

        self.bts_basic_info.wait_for_visibility_by_xpath\
            .assert_called_once_with(button_xpath, expected_timeout)
        self.bts_basic_info._can_be_connected_to_bts.assert_called_once()
        self.bts_basic_info.click_enabled_element.\
            assert_called_once_with((By.XPATH, button_xpath), timeout=5)
        self.bts_basic_info.wait_for_text_not_present_in_element.\
            assert_called_once_with((By.XPATH, bts_id_xpath), '---', timeout=30)

    def test_reconnect_without_dropdown_list_cant_be_connected_to_bts(self):
        expected_timeout = 5
        button_xpath = self.bts_basic_info._CONNECT_DISCONNECT_BUTTON_XPATH
        bts_id_xpath = self.bts_basic_info._BTS_ID_XPATH
        self.bts_basic_info.wait_for_visibility_by_xpath = mock.Mock()
        self.bts_basic_info._can_be_connected_to_bts = mock.Mock(return_value=False)
        self.bts_basic_info.wait_for_text_not_present_in_element = mock.Mock()
        self.bts_basic_info.click_enabled_element = mock.Mock()

        self.bts_basic_info._reconnect_without_dropdown_list(expected_timeout)

        self.bts_basic_info.wait_for_visibility_by_xpath\
            .assert_called_once_with(button_xpath, expected_timeout)
        self.bts_basic_info._can_be_connected_to_bts.assert_called_once()
        self.bts_basic_info.click_enabled_element.assert_not_called()

        self.bts_basic_info.wait_for_text_not_present_in_element.\
            assert_called_once_with((By.XPATH, bts_id_xpath), '---', timeout=30)
